$$('[data-account-help]').forEach(button=>button.onclick=()=>showAuthDialog('Recuperar acesso','<p>Para recuperar sua conta com segurança, fale com o suporte pelo Instagram e informe apenas o e-mail cadastrado. Nunca envie sua senha.</p><a href="https://instagram.com/rlkdn.dev" target="_blank" rel="noopener">Abrir suporte</a>','CONTA'));
