for(let i=0;i<16;i++){const particle=document.createElement('i');particle.style.setProperty('--x',`${Math.random()*100}%`);particle.style.setProperty('--d',`${7+Math.random()*8}s`);particle.style.setProperty('--delay',`${Math.random()*8}s`);$('.auth-particles').appendChild(particle);}
