async function loadAll(){
  [state.dashboard,state.animals,state.water,state.drones,state.notifications,state.social,state.weather,state.settings,state.billing,state.nfc,state.announcements]=await Promise.all([
    request('/api/dashboard'),request('/api/animals'),request('/api/water'),request('/api/drones'),request('/api/notifications'),request('/api/social'),
    request('/api/weather').catch(()=>({available:false,city:state.farm?.city})),request('/api/settings'),request('/api/billing'),request('/api/nfc'),request('/api/announcements')
  ]);applySettings();
}
async function enterApp(){showOnly('appView');renderSkeleton();try{await loadAll();route('dashboard',true);}catch(e){toast(e.message,true);}}

const screens={dashboard:renderHome,community:renderCommunity,challenges:renderChallenges,profile:renderProfile,editProfile:renderEditProfile,farmFeed:renderFarmFeed,nfc:renderNfc,animals:renderAnimals,water:renderWater,drones:renderDrones,alerts:renderAlerts,property:renderProperty,contacts:renderContacts,credits:renderCredits,settings:renderSettings,plans:renderPlans,farmProfile:renderFarmProfile,admin:renderAdmin};
function route(name,replace=false){
  if(!replace)state.scroll[state.route]=window.scrollY;state.route=name;
  $$('.bottom-nav [data-route]').forEach(button=>button.classList.toggle('active',button.dataset.route===name));
  (screens[name]||renderHome)();injectAnnouncements();
  requestAnimationFrame(()=>window.scrollTo({top:state.scroll[name]||0,behavior:'auto'}));
}
function avatarMarkup(url,name,className='farm-avatar'){return url?`<span class="${className} avatar-image"><img src="${esc(url)}" alt="Foto de ${esc(name)}"></span>`:`<span class="${className}">${esc(initials(name))}</span>`;}
function injectAnnouncements(){
  if(state.route==='admin'||!state.announcements.length)return;const dismissed=new Set(JSON.parse(localStorage.getItem('hydra-dismissed-announcements')||'[]')),visible=state.announcements.filter(item=>!dismissed.has(item.id));if(!visible.length)return;const host=document.createElement('div');host.className='global-announcements';host.innerHTML=visible.map(item=>`<article class="global-notice ${item.type}"><span>${icon(item.type==='maintenance'?'settings':item.type==='update'?'arrow':'megaphone')}</span><div><small>${item.type==='maintenance'?'MANUTENÇÃO':item.type==='update'?'ATUALIZAÇÃO':'AVISO'}</small><strong>${esc(item.title)}</strong><p>${esc(item.message)}</p></div><button data-dismiss-announcement="${item.id}" aria-label="Fechar aviso">${icon('close')}</button></article>`).join('');$('#pageRoot').prepend(host);$$('[data-dismiss-announcement]',host).forEach(button=>button.onclick=()=>{dismissed.add(Number(button.dataset.dismissAnnouncement));localStorage.setItem('hydra-dismissed-announcements',JSON.stringify([...dismissed]));button.closest('.global-notice').remove();if(!host.children.length)host.remove();});
}
document.addEventListener('click',event=>{
  const routeButton=event.target.closest('[data-route]');if(routeButton){event.preventDefault();route(routeButton.dataset.route);return;}
  const action=event.target.closest('[data-action]');if(action?.dataset.action==='create')openQuickMenu();if(action?.dataset.action==='nfc')openNfc();
});

function greeting(){const hour=new Date().getHours();return hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';}
function weekStrip(){const today=new Date(),start=new Date(today);start.setDate(today.getDate()-today.getDay());const labels=['D','S','T','Q','Q','S','S'];return `<div class="week-strip-app">${labels.map((label,index)=>{const day=new Date(start);day.setDate(start.getDate()+index);const active=day.toDateString()===today.toDateString();return `<span class="${active?'today':''}"><small>${label}</small><b>${day.getDate()}</b></span>`;}).join('')}</div>`;}
function weatherLabel(code){if(code===0)return['☀️','Céu limpo'];if([1,2,3].includes(code))return['⛅','Parcialmente nublado'];if([45,48].includes(code))return['🌫️','Neblina'];if(code>=51&&code<=67)return['🌧️','Chuva'];if(code>=80&&code<=82)return['🌦️','Pancadas de chuva'];if(code>=95)return['⛈️','Tempestade'];return['🌤️','Clima atual'];}
function countUp(){
  if(!Number(state.settings.animations)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  $$('[data-count]').forEach(el=>{const target=Number(el.dataset.count)||0,start=performance.now(),duration=650;const frame=now=>{const p=Math.min(1,(now-start)/duration);el.textContent=number(Math.round(target*(1-Math.pow(1-p,3))));if(p<1)requestAnimationFrame(frame);};requestAnimationFrame(frame);});
}
function renderHome(){
  const d=state.dashboard,first=esc(state.user.name.split(' ')[0]),goal=d.waterGoal||3500,pct=Math.min(100,Math.round((d.todayWater/goal)*100)||0),low=d.reservoirs.find(r=>r.level<30),weather=weatherLabel(state.weather.code),unread=state.notifications.some(n=>!n.read),completed=state.social.challenges.filter(c=>c.progress>=c.target),hasProgress=Boolean(d.todayWater||d.animalStats.total||state.drones.length||completed.length);
  const today=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date());
  const next=d.tasks.slice(0,3);
  $('#pageRoot').innerHTML=`<section class="screen approved-home"><header class="approved-topbar"><div class="mini-brand"><img src="/logo.svg" alt="Hydra Agro"><strong>Hydra <span>Agro</span></strong></div><button class="icon-button" data-route="alerts" aria-label="Notificações">${icon('bell')}${unread?'<i class="dot"></i>':''}</button></header><div class="approved-greeting"><div><small>${greeting()}</small><h1>Olá, ${first}</h1></div><button class="approved-weather" id="refreshWeather"><strong>${state.weather.available?`${state.weather.temperature}°`:'--'}</strong><small>${state.weather.available?`${weather[1]} · ${esc(state.farm.city)}`:'Atualizar clima'}</small></button></div>${weekStrip()}<article class="approved-farm-panel"><header><small>VISÃO DE HOJE</small><button data-route="property">Abrir fazenda →</button></header><h2>${esc(state.farm.name)}</h2><div class="approved-metrics"><div><small>Água</small><strong><i data-count="${d.todayWater}">0</i> L</strong></div><div><small>Animais</small><strong data-count="${d.animalStats.total}">0</strong></div><div><small>Drones</small><strong data-count="${d.dronesActive}">0</strong></div></div><footer><div><small>Meta diária</small><i><b style="width:${pct}%"></b></i></div><strong>${pct}%</strong></footer></article><div class="approved-section"><h2>Acessos rápidos</h2><button id="quickInfo">Organizar</button></div><div class="approved-quick-grid"><button data-route="animals"><span>${icon('cow')}</span><strong>Rebanho</strong><small>Cadastro e identificação</small></button><button class="orange" data-route="nfc"><span>${icon('nfc')}</span><strong>Leitura NFC</strong><small>${state.nfc.stats.scans} leituras realizadas</small></button><button data-route="water"><span>${icon('drop')}</span><strong>Água</strong><small>Consumo e reservatórios</small></button><button data-route="drones"><span>${icon('drone')}</span><strong>Drones</strong><small>Missões e dispositivos</small></button></div><div class="approved-section"><h2>Próximos passos</h2><button data-route="challenges">Ver progresso</button></div><article class="approved-list">${next.map(task=>`<button data-route="${esc(task.route)}"><span>${icon(task.type==='water'?'drop':task.type==='animal'?'cow':'drone')}</span><div><strong>${esc(task.title)}</strong><small>Atualize os dados reais da fazenda</small></div>${icon('chevron')}</button>`).join('')||`<button data-route="challenges"><span>${icon('check')}</span><div><strong>Tudo em dia</strong><small>${d.sustainabilityScore} pontos sustentáveis · ${d.streak} dias na meta</small></div>${icon('chevron')}</button>`}</article><button class="approved-tip" data-route="alerts"><span>${icon(low?'drop':'leaf')}</span><div><strong>${low?'Atenção necessária':'Dica de hoje'}</strong><small>${low?`${esc(low.name)} está com ${low.level}% de capacidade.`:esc(d.tip)}</small></div>${icon('chevron')}</button></section>`;
  $('#quickInfo').onclick=()=>toast('Mantenha pressionado um atalho para organizar.');
  $('#refreshWeather').onclick=refreshWeather;countUp();
}

async function refreshWeather(){const button=$('#refreshWeather');button.classList.add('loading-weather');try{state.weather=await request('/api/weather');renderHome();toast(state.weather.available?'Clima atualizado.':'Clima indisponível no momento.',!state.weather.available);}catch(e){toast(e.message,true);}finally{button?.classList.remove('loading-weather');}}

function filteredPosts(){return state.social.posts.filter(post=>{
  const tabOk=state.communityTab==='all'||(state.communityTab==='following'&&(post.followed||post.mine))||(state.communityTab==='mine'&&post.mine);
  const filterOk=state.communityFilter==='all'||(state.communityFilter==='saved'&&post.saved)||post.category===state.communityFilter;
  const q=state.communityQuery.toLowerCase(),queryOk=!q||`${post.content} ${post.farm_name} ${post.category}`.toLowerCase().includes(q);return tabOk&&filterOk&&queryOk;
});}
function initials(value){return String(value||'HA').split(' ').map(p=>p[0]).slice(0,2).join('').toUpperCase();}
function communityPost(post){
  return `<article class="card post" data-post-id="${post.id}"><header class="post-header"><button class="farm-avatar farm-link ${post.author_avatar?'avatar-image':''}" data-farm="${post.farm_id}" aria-label="Abrir ${esc(post.farm_name)}">${post.author_avatar?`<img src="${esc(post.author_avatar)}" alt="">`:esc(initials(post.farm_name))}</button><button class="post-author farm-link" data-farm="${post.farm_id}"><strong>${esc(post.farm_name)}</strong><small>${esc(post.farm_city)} - ${esc(post.farm_state)} · ${ago(post.created_at)}</small></button>${!post.mine?`<button class="follow-mini ${post.followed?'following':''}" data-follow="${post.farm_id}">${post.followed?'Seguindo':'Seguir'}</button>`:''}<button class="post-menu" data-post-menu="${post.id}" aria-label="Mais opções">•••</button></header><span class="post-category">${esc(post.category)}</span><p class="post-text">${esc(post.content)}</p>${post.image_url?`<img class="user-post-image" src="${esc(post.image_url)}" alt="Imagem enviada na publicação" loading="lazy">`:''}<footer class="post-actions"><button class="like-button ${post.liked?'liked':''}" data-like="${post.id}" aria-label="${post.liked?'Descurtir':'Curtir'}">${icon('heart')} <span>${number(post.reactions)}</span><i class="like-particles"></i></button><button data-comments="${post.id}">${icon('comment')} <span>${number(post.comments)}</span></button><button data-share="${post.id}">${icon('share')} <span>Compartilhar</span></button><button class="bookmark ${post.saved?'saved':''}" data-save="${post.id}" aria-label="${post.saved?'Remover dos salvos':'Salvar'}">${icon('bookmark')}</button></footer></article>`;
}
function renderCommunity(){
  const posts=filteredPosts(),filterLabel=state.communityFilter==='all'?'':`<span class="active-filter">${state.communityFilter==='saved'?'Salvos':esc(state.communityFilter)} <button id="clearFilter">×</button></span>`;
  $('#pageRoot').innerHTML=`<section class="screen community-screen approved-community"><div id="pullIndicator" class="pull-indicator">${icon('arrow')}<span>Puxe para atualizar</span></div><span class="approved-eyebrow">REDE RURAL</span><header class="approved-page-title"><h1>Comunidade</h1><div><button class="icon-button" id="toggleSearch" aria-label="Buscar">${icon('search')}</button><button class="icon-button" id="openFilter" aria-label="Filtrar">${icon('filter')}</button></div></header><div class="search-bar community-search ${state.communityQuery?'':'collapsed'}">${icon('search')}<input id="communitySearch" placeholder="Buscar no feed" value="${esc(state.communityQuery)}"></div>${filterLabel}<div class="community-tabs"><button data-tab="all" class="${state.communityTab==='all'?'active':''}">Todos</button><button data-tab="following" class="${state.communityTab==='following'?'active':''}">Seguindo</button><button data-tab="mine" class="${state.communityTab==='mine'?'active':''}">Minhas fazendas</button></div><div class="card composer approved-composer">${avatarMarkup(state.user.avatar_url,state.user.name)}<button id="composerButton">Compartilhe algo da sua fazenda</button><button class="composer-camera" id="composerCamera" aria-label="Publicar foto">${icon('camera')}</button></div><div class="feed">${posts.map(communityPost).join('')||'<div class="card empty approved-empty"><span>'+icon('users')+'</span><strong>O feed começa com a comunidade</strong><small>As publicações reais das propriedades aparecerão aqui.</small></div>'}</div></section>`;
  $('#composerButton').onclick=()=>openPostForm();$('#composerCamera').onclick=()=>openPostForm(null,true);$('#openFilter').onclick=openCommunityFilter;
  $('#toggleSearch').onclick=()=>{const bar=$('.community-search');bar.classList.toggle('collapsed');if(!bar.classList.contains('collapsed'))$('#communitySearch').focus();};
  $('#communitySearch').oninput=e=>{state.communityQuery=e.target.value;clearTimeout(renderCommunity.searchTimer);renderCommunity.searchTimer=setTimeout(renderCommunity,180);};
  $('#clearFilter')?.addEventListener('click',()=>{state.communityFilter='all';renderCommunity();});
  $$('[data-tab]').forEach(button=>button.onclick=()=>{state.communityTab=button.dataset.tab;renderCommunity();});
  $$('[data-like]').forEach(button=>button.onclick=()=>toggleLike(button));$$('[data-comments]').forEach(button=>button.onclick=()=>openComments(Number(button.dataset.comments)));$$('[data-save]').forEach(button=>button.onclick=()=>toggleSave(button));$$('[data-share]').forEach(button=>button.onclick=()=>sharePost(Number(button.dataset.share)));$$('[data-post-menu]').forEach(button=>button.onclick=()=>openPostMenu(Number(button.dataset.postMenu)));$$('[data-follow]').forEach(button=>button.onclick=()=>toggleFollow(Number(button.dataset.follow)));$$('[data-farm]').forEach(button=>button.onclick=()=>openFarm(Number(button.dataset.farm)));
  setupPullToRefresh();
}
async function refreshSocial(message=true){state.social=await request('/api/social');if(state.route==='community')renderCommunity();if(message)toast('Feed atualizado.');}
async function toggleLike(button){if(button.disabled)return;button.disabled=true;try{const result=await request(`/api/posts/${button.dataset.like}/like`,{method:'POST'});button.classList.toggle('liked',result.liked);$('span',button).textContent=number(result.count);button.setAttribute('aria-label',result.liked?'Descurtir':'Curtir');if(result.liked){button.classList.add('like-pop');setTimeout(()=>button.classList.remove('like-pop'),500);}const post=state.social.posts.find(p=>p.id===Number(button.dataset.like));if(post){post.liked=result.liked;post.reactions=result.count;}}catch(e){toast(e.message,true);}finally{button.disabled=false;}}
async function toggleSave(button){button.disabled=true;try{const result=await request(`/api/posts/${button.dataset.save}/save`,{method:'POST'});button.classList.toggle('saved',result.saved);const post=state.social.posts.find(p=>p.id===Number(button.dataset.save));if(post)post.saved=result.saved;toast(result.saved?'Publicação salva.':'Removida dos salvos.');}catch(e){toast(e.message,true);}finally{button.disabled=false;}}
async function toggleFollow(farmId){try{const result=await request(`/api/farms/${farmId}/follow`,{method:'POST'});state.social.posts.filter(p=>p.farm_id===farmId).forEach(p=>p.followed=result.followed);if(state.route==='farmProfile')await openFarm(farmId);else renderCommunity();toast(result.followed?'Fazenda seguida.':'Você deixou de seguir.');}catch(e){toast(e.message,true);}}
async function sharePost(postId){const post=state.social.posts.find(p=>p.id===postId);if(!post)return;const share={title:`${post.farm_name} no Hydra Agro`,text:post.content,url:location.origin,dialogTitle:'Compartilhar publicação'};try{const nativeShare=window.Capacitor?.Plugins?.Share;if(nativeShare)await nativeShare.share(share);else if(navigator.share)await navigator.share(share);else{await navigator.clipboard.writeText(`${share.title}\n${share.text}\n${share.url}`);toast('Texto copiado para compartilhar.');}}catch(e){if(e.name!=='AbortError'&&e.message!=='Share canceled')toast('Não foi possível compartilhar.',true);}}
function openCommunityFilter(){
  const options=['all','saved','Economia de água','Rebanho','Tecnologia','Conquista'];openModal('FILTROS','Filtrar publicações',`<form id="filterForm" class="choice-list">${options.map(value=>`<label><input type="radio" name="filter" value="${esc(value)}" ${state.communityFilter===value?'checked':''}><span>${value==='all'?'Todas as categorias':value==='saved'?'Somente salvos':esc(value)}</span></label>`).join('')}<button class="main-button green-button" type="submit">Aplicar filtro</button></form>`);$('#filterForm').onsubmit=e=>{e.preventDefault();state.communityFilter=new FormData(e.currentTarget).get('filter');closeModal();renderCommunity();};
}
function setupPullToRefresh(){
  state.pullCleanup?.();const screen=$('.community-screen');if(!screen)return;let start=0,distance=0;const begin=e=>{if(window.scrollY<=0)start=e.touches[0].clientY;};const move=e=>{if(!start)return;distance=Math.max(0,Math.min(95,e.touches[0].clientY-start));const indicator=$('#pullIndicator');indicator.style.transform=`translateY(${distance}px)`;indicator.classList.toggle('ready',distance>65);};const end=async()=>{const refresh=distance>65;start=distance=0;const indicator=$('#pullIndicator');if(indicator)indicator.style.transform='';if(refresh){indicator?.classList.add('refreshing');try{await refreshSocial(false);toast('Feed atualizado.');}catch(e){toast(e.message,true);}}};screen.addEventListener('touchstart',begin,{passive:true});screen.addEventListener('touchmove',move,{passive:true});screen.addEventListener('touchend',end);state.pullCleanup=()=>{screen.removeEventListener('touchstart',begin);screen.removeEventListener('touchmove',move);screen.removeEventListener('touchend',end);};
}

function challengeCard(challenge,index){const pct=Math.min(100,Math.round(challenge.progress/challenge.target*100)),source=index===0?'Atualizado pelas leituras de água':index===1?'Atualizado pelas leituras NFC':'Atualizado ao concluir missões';return `<article class="card challenge-card"><div class="challenge-main"><span class="challenge-icon">${icon(index===0?'drop':index===1?'cow':'drone')}</span><div><strong>${esc(challenge.title)}</strong><p>${esc(challenge.description)}</p></div><b>${challenge.progress}/${challenge.target}</b></div><div class="progress-bar ${index===1?'green':''}"><i style="width:${pct}%"></i></div><footer><span>${pct===100?'Concluído':source}</span><strong>${pct}%</strong></footer></article>`;}
function rankingMarkup(){return `<div class="ranking-list">${state.social.ranking.map(rank=>`<div class="rank-row ${rank.mine?'mine':''}"><b>${rank.position||'—'}</b><span>${esc(initials(rank.name))}</span><div><strong>${esc(rank.name)}</strong><small>${esc(rank.city)}</small></div><em>${rank.qualified?`${rank.saving}%`:'Sem dados'}</em></div>`).join('')}</div>`;}
function openRanking(){openModal('RANKING SUSTENTÁVEL','Ranking geral',rankingMarkup());}
function renderChallenges(){
  const mine=state.social.ranking.find(item=>item.mine)||{position:0,saving:0,qualified:false};$('#pageRoot').innerHTML=`<section class="screen"><header class="screen-header"><h1>Desafios</h1><button class="icon-button" id="challengeInfo" aria-label="Como funciona">${icon('info')}</button></header><article class="ranking-hero"><div class="hero-main"><span class="trophy-circle">${icon('trophy')}</span><div><small>${mine.qualified?'Você está em':'Ranking sustentável'}</small><strong>${mine.qualified?`${mine.position}º lugar`:'Sem posição'}</strong><span>${mine.qualified?`${mine.saving}% de economia calculada`:'Registre consumo para participar'}</span></div></div><button class="ranking-footer" id="rankingHero"><span>Ver ranking completo</span><span>›</span></button></article><div class="section-heading"><h2>Seus desafios</h2></div><div class="challenge-list">${state.social.challenges.map(challengeCard).join('')}</div><div class="section-heading"><h2>Ranking geral</h2><button id="rankingAll">Ver tudo</button></div><article class="card">${rankingMarkup()}</article></section>`;
  $('#rankingHero').onclick=openRanking;$('#rankingAll').onclick=openRanking;$('#challengeInfo').onclick=()=>openModal('DESAFIOS','Como funciona',`<div class="info-copy"><p>Não existe progresso manual. As metas avançam quando você registra água dentro da meta, lê uma etiqueta NFC cadastrada ou encerra uma missão de drone voltando o status para “Na base”.</p><button class="main-button green-button" data-close>Entendi</button></div>`);
}

function renderProfile(){
  const unread=state.notifications.filter(n=>!n.read).length,posts=state.social.posts.filter(p=>p.mine).length,plan=state.billing.current.plan==='pro'?(state.billing.current.vip?'VIP do proprietário':'Hydra Agro Pro'):'Plano gratuito';
  const row=(route,ico,title,subtitle,badge='')=>`<button class="profile-menu-row" data-route="${route}"><span class="profile-menu-icon">${icon(ico)}</span><span><strong>${title}</strong><small>${subtitle}</small></span>${badge?`<b>${badge}</b>`:''}${icon('chevron')}</button>`;
  $('#pageRoot').innerHTML=`<section class="screen approved-profile"><header class="approved-profile-head"><span class="approved-eyebrow">MINHA CONTA</span><div>${avatarMarkup(state.user.avatar_url,state.user.name,'approved-profile-avatar')}<section><h1>${esc(state.user.name)} ${state.billing.current.plan==='pro'?`<em>${state.billing.current.vip?'VIP':'PRO'}</em>`:''}</h1><p>${esc(state.farm.name)} · ${esc(state.farm.city)}, ${esc(state.farm.state)}</p></section><button data-route="editProfile">Editar</button></div></header><button class="approved-plan" data-route="plans"><span>${icon('trophy')}</span><div><strong>${plan}</strong><small>${state.billing.current.plan==='pro'?'Recursos premium ativos':'Conheça o plano Hydra Agro Pro'}</small></div>${icon('chevron')}</button><section class="profile-section-v2"><h2>Fazenda</h2><article class="profile-menu-card">${row('property','clipboard','Informações da propriedade','Localização, área, atividade e metas')}${row('farmFeed','users','Feed da fazenda',`${posts} publicaç${posts===1?'ão':'ões'}`,posts)}${row('nfc','nfc','Central NFC',`${state.nfc.stats.scans} leituras realizadas`,state.nfc.stats.scans)}${row('drones','drone','Dispositivos conectados',`${state.drones.length} dispositivos`,state.drones.length)}</article></section><section class="profile-section-v2"><h2>Aplicativo</h2><article class="profile-menu-card">${row('alerts','bell','Notificações',unread?'Existem avisos não lidos':'Tudo em dia',unread)}${row('settings','settings','Configurações','Tema, animações e NFC')}${row('contacts','phone','Ajuda e suporte','Canais oficiais do aplicativo')}${row('credits','info','Sobre o aplicativo','Créditos e versão')}</article></section>${isOwner()?`<section class="profile-section-v2"><h2>Administração</h2><article class="profile-menu-card">${row('admin','shield','Painel administrativo','Avisos, usuários e manutenção','ADM')}</article></section>`:''}<button class="profile-logout-v2" id="logoutButton">${icon('logout')} Sair da conta</button></section>`;$('#logoutButton').onclick=logout;
}

function renderEditProfile(){
  $('#pageRoot').innerHTML=`<section class="screen">${subHeader('Editar perfil','', 'profile')}<form id="profileForm" class="card page-form profile-edit-form"><div class="profile-photo-editor">${avatarMarkup(state.user.avatar_url,state.user.name,'profile-photo-preview')}<label for="profileGallery">${icon('camera')} Escolher foto</label><input id="profileGallery" type="file" accept="image/*">${state.user.avatar_url?'<button type="button" id="removeAvatar">Remover foto</button>':''}</div><label>Seu nome<input name="name" value="${esc(state.user.name)}" required minlength="2"></label><label>E-mail<input value="${esc(state.user.email)}" disabled></label><div class="form-error"></div><button class="main-button orange-button" type="submit">Salvar perfil</button></form></section>`;let avatar=null,removeAvatar=false;$('#profileGallery').onchange=async e=>{try{avatar=await imageData(e.target.files[0]);removeAvatar=false;$('.profile-photo-preview').outerHTML=`<span class="profile-photo-preview avatar-image"><img src="${avatar}" alt="Prévia"></span>`;}catch(error){$('.form-error',$('#pageRoot')).textContent=error.message;}};$('#removeAvatar')?.addEventListener('click',()=>{avatar=null;removeAvatar=true;$('.profile-photo-preview').outerHTML=`<span class="profile-photo-preview">${esc(initials(state.user.name))}</span>`;$('#removeAvatar').remove();});$('#profileForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=$('button[type=submit]',form);loading(button,true,'Salvando...');try{state.user=await request('/api/profile',{method:'PATCH',body:{name:form.name.value,avatar,removeAvatar}});state.social=await request('/api/social');closeModal();toast('Perfil atualizado.');route('profile');}catch(error){$('.form-error',form).textContent=error.message;}finally{loading(button,false);}};
}

function bindPostActions(root=document){$$('[data-like]',root).forEach(button=>button.onclick=()=>toggleLike(button));$$('[data-comments]',root).forEach(button=>button.onclick=()=>openComments(Number(button.dataset.comments)));$$('[data-save]',root).forEach(button=>button.onclick=()=>toggleSave(button));$$('[data-share]',root).forEach(button=>button.onclick=()=>sharePost(Number(button.dataset.share)));$$('[data-post-menu]',root).forEach(button=>button.onclick=()=>openPostMenu(Number(button.dataset.postMenu)));$$('[data-follow]',root).forEach(button=>button.onclick=()=>toggleFollow(Number(button.dataset.follow)));$$('[data-farm]',root).forEach(button=>button.onclick=()=>openFarm(Number(button.dataset.farm)));}
function renderFarmFeed(){const posts=state.social.posts.filter(post=>post.mine);$('#pageRoot').innerHTML=`<section class="screen">${subHeader('Feed da fazenda','', 'profile')}<div class="farm-feed-head">${avatarMarkup(state.user.avatar_url,state.farm.name,'farm-avatar')}<div><strong>${esc(state.farm.name)}</strong><small>${posts.length} publicaç${posts.length===1?'ão':'ões'}</small></div><button class="primary-small" id="farmFeedPost">+ Publicar</button></div><div class="feed">${posts.map(communityPost).join('')||'<div class="card empty">Sua fazenda ainda não publicou. Use o botão acima para criar a primeira publicação.</div>'}</div></section>`;$('#farmFeedPost').onclick=()=>openPostForm();bindPostActions($('#pageRoot'));}

function subHeader(title,action='',back='dashboard'){return `<div class="subpage-title"><button class="icon-button back-button" data-route="${back}">${icon('back')}</button><h1>${title}</h1>${action}</div>`;}
function renderNfc(){
  const n=state.nfc,pct=n.stats.registered?Math.round(n.stats.identified/n.stats.registered*100):0;$('#pageRoot').innerHTML=`<section class="screen nfc-screen">${subHeader('Central NFC')}<article class="nfc-hero"><div class="nfc-rings nfc-rings-large"><i></i><i></i>${icon('nfc')}</div><small>IDENTIFICAÇÃO DO REBANHO</small><h2>Aproxime uma etiqueta</h2><p>Leia brincos NFC, encontre o cadastro do animal e registre automaticamente a última identificação.</p><button class="main-button orange-button" id="startNfcScan">Iniciar leitura NFC</button></article><div class="nfc-stats"><article class="card"><strong>${n.stats.registered}</strong><small>Etiquetas cadastradas</small></article><article class="card"><strong>${n.stats.identified}</strong><small>Animais identificados</small></article><article class="card"><strong>${n.stats.scans}</strong><small>Leituras realizadas</small></article></div><article class="card nfc-progress"><div><strong>Cobertura NFC</strong><span>${pct}%</span></div><i><b style="width:${pct}%"></b></i></article><form id="manualNfcForm" class="card manual-nfc-form"><label>Digitar código manualmente<input name="tag" placeholder="AG-0001" required></label><button type="submit">Identificar</button></form><div class="section-heading"><h2>Histórico de leituras</h2></div><div class="nfc-history">${n.history.map(scan=>`<article class="card nfc-history-row"><span class="${scan.result==='identified'?'success':'unknown'}">${icon(scan.result==='identified'?'check':'nfc')}</span><div><strong>${scan.animal_name?esc(scan.animal_name):esc(scan.tag)}</strong><small>${scan.animal_name?`${esc(scan.tag)} · ${esc(scan.animal_status)}`:'Etiqueta ainda não cadastrada'} · ${ago(scan.scanned_at)}</small></div>${scan.animal_id?`<button data-route="animals">Ver</button>`:`<button data-register-tag="${esc(scan.tag)}">Cadastrar</button>`}</article>`).join('')||'<div class="card empty">Nenhuma leitura NFC realizada.</div>'}</div></section>`;$('#startNfcScan').onclick=openNfc;$('#manualNfcForm').onsubmit=e=>{e.preventDefault();processNfcScan(e.currentTarget.tag.value);};$$('[data-register-tag]').forEach(button=>button.onclick=()=>openAnimalForm(button.dataset.registerTag));
}
function renderAnimals(filter=''){
  const list=state.animals.filter(animal=>`${animal.name} ${animal.tag} ${animal.breed} ${animal.sector}`.toLowerCase().includes(filter.toLowerCase()));$('#pageRoot').innerHTML=`<section class="screen">${subHeader('Rebanho',`<button class="primary-small" id="addAnimal">+ Novo animal</button>`)}<div class="search-bar">${icon('search')}<input id="animalSearch" placeholder="Buscar por nome ou etiqueta" value="${esc(filter)}"></div><div class="animal-list">${list.map(animal=>`<article class="card animal-row"><span class="animal-bubble">${icon('cow')}</span><div><strong>${esc(animal.name)}</strong><small>${esc(animal.tag)} · ${esc(animal.breed)} · ${esc(animal.sector)}</small></div><span class="status ${animal.status==='Saudável'?'':'watch'}">${esc(animal.status)}</span></article>`).join('')||'<div class="empty">Nenhum animal encontrado.</div>'}</div></section>`;$('#animalSearch').oninput=e=>renderAnimals(e.target.value);$('#addAnimal').onclick=()=>openAnimalForm();
}
function waterSaving(){const values=state.water.history.map(i=>Number(i.liters));if(values.length<2)return 0;const previous=values.slice(0,-1).reduce((a,b)=>a+b,0)/(values.length-1);return Math.round((1-values.at(-1)/Math.max(1,previous))*100);}
function renderWater(){
  const max=Math.max(...state.water.history.map(item=>item.liters),1),saving=waterSaving();$('#pageRoot').innerHTML=`<section class="screen">${subHeader('Gestão da água')}<div class="water-actions"><button class="primary-small" id="addWater">+ Registrar consumo</button><button class="primary-small secondary-small" id="addReservoir">+ Reservatório</button></div><div class="reservoir-list">${state.water.reservoirs.map(item=>`<article class="card reservoir-row"><div class="row-top"><div><h3>${esc(item.name)}</h3><p>${esc(item.sector)} · ${number(item.capacity)} L</p></div><b class="${item.level<30?'low':''}">${item.level}%</b></div><div class="level-track"><i class="${item.level<30?'low':''}" style="width:${item.level}%"></i></div><div class="row-foot"><span>Nível atual</span><button data-reservoir="${item.id}" data-level="${item.level}">Atualizar</button></div></article>`).join('')||'<div class="card empty">Nenhum reservatório cadastrado.</div>'}</div><div class="section-heading"><h2>Últimos 7 dias</h2>${state.water.history.length?`<span class="saving-label ${saving<0?'negative':''}">${saving>=0?'−':'+'}${Math.abs(saving)}% no período</span>`:''}</div>${state.water.history.length?`<article class="card charts">${state.water.history.map(item=>`<div class="chart-col"><i style="height:${Math.max(12,item.liters/max*88)}%" title="${number(item.liters)} L"></i><small>${weekday(item.day)}</small></div>`).join('')}</article>`:'<div class="card empty">O gráfico começará após a primeira leitura de água.</div>'}</section>`;$('#addWater').onclick=openWaterForm;$('#addReservoir').onclick=openReservoirCreate;$$('[data-reservoir]').forEach(button=>button.onclick=()=>openReservoirForm(button.dataset.reservoir,button.dataset.level));
}
function renderDrones(){
  $('#pageRoot').innerHTML=`<section class="screen">${subHeader('Drones',`<button class="primary-small" id="addDrone">+ Drone</button>`)}<div class="drone-list">${state.drones.map(drone=>`<article class="card drone-row"><div class="row-top"><div><h3>${esc(drone.name)}</h3><p>${esc(drone.model)}</p></div><span class="status ${drone.status==='Em voo'?'':'watch'}">${esc(drone.status)}</span></div><div class="drone-status-visual">${icon('drone')}<strong>${esc(drone.mission)}</strong></div><div class="row-foot"><span>Bateria</span><strong>${drone.battery}%</strong></div><div class="level-track"><i style="width:${drone.battery}%"></i></div><button class="manage-button" data-drone="${drone.id}">Gerenciar missão</button></article>`).join('')||'<div class="card empty">Nenhum drone cadastrado.</div>'}</div></section>`;$('#addDrone').onclick=()=>openDroneForm();$$('[data-drone]').forEach(button=>button.onclick=()=>openDroneForm(state.drones.find(d=>d.id===Number(button.dataset.drone))));
}
function renderAlerts(){
  const unread=state.notifications.some(n=>!n.read);$('#pageRoot').innerHTML=`<section class="screen">${subHeader('Notificações',unread?'<button class="primary-small" id="readAll">Marcar lidas</button>':'')}<div class="notice-list">${state.notifications.map(item=>`<button class="card notice-row ${item.read?'':'unread'}" data-route="${item.type==='animal'?'animals':item.type==='warning'?'water':'challenges'}"><span class="notice-bubble">${icon(item.type==='animal'?'cow':item.type==='success'?'leaf':'bell')}</span><div><strong>${esc(item.title)}</strong><small>${esc(item.message)} · ${ago(item.created_at)}</small></div>${icon('chevron')}</button>`).join('')||'<div class="card empty">Nenhuma notificação.</div>'}</div></section>`;$('#readAll')?.addEventListener('click',async()=>{try{await request('/api/notifications/read',{method:'POST'});state.notifications.forEach(n=>n.read=1);renderAlerts();toast('Notificações marcadas como lidas.');}catch(e){toast(e.message,true);}});
}

