function renderFarmProfile(){
  const farm=state.farmProfile;if(!farm)return route('community');const posts=state.social.posts.filter(p=>p.farm_id===farm.id),followed=posts.some(p=>p.followed);$('#pageRoot').innerHTML=`<section class="screen">${subHeader('Perfil da fazenda','', 'community')}<div class="public-farm-hero">${avatarMarkup(farm.owner_avatar,farm.name,'farm-profile-avatar')}<h1>${esc(farm.name)}</h1><p>${icon('location')} ${esc(farm.city)} - ${esc(farm.state)}</p><small>${esc(farm.activity)} · ${number(farm.area)} ha</small><button class="main-button ${followed?'outline-button':'orange-button'}" id="profileFollow">${followed?'Deixar de seguir':'Seguir propriedade'}</button></div><article class="card profile-stats"><div>${icon('cow')}<strong>${farm.animals}</strong><small>Animais</small></div><div>${icon('users')}<strong>${farm.followers}</strong><small>Seguidores</small></div><div>${icon('clipboard')}<strong>${farm.posts}</strong><small>Publicações</small></div></article><div class="section-heading"><h2>Publicações</h2></div><div class="feed">${posts.map(communityPost).join('')||'<div class="card empty">Esta fazenda ainda não publicou.</div>'}</div></section>`;$('#profileFollow').onclick=()=>toggleFollow(farm.id);bindPostActions($('#pageRoot'));
}

function openQuickMenu(){openModal('AÇÃO RÁPIDA','O que deseja fazer?',`<div class="quick-menu"><button id="quickPost"><span>${icon('leaf')}</span><div><strong>Nova publicação</strong><small>Compartilhar no feed</small></div>${icon('chevron')}</button><button id="quickAnimal"><span>${icon('cow')}</span><div><strong>Cadastrar animal</strong><small>Adicionar ao rebanho</small></div>${icon('chevron')}</button><button id="quickNfc"><span>${icon('nfc')}</span><div><strong>Ler etiqueta NFC</strong><small>Identificar um animal</small></div>${icon('chevron')}</button><button id="quickWater"><span>${icon('drop')}</span><div><strong>Registrar consumo</strong><small>Adicionar leitura de água</small></div>${icon('chevron')}</button></div>`);$('#quickPost').onclick=()=>swapModal(()=>openPostForm());$('#quickAnimal').onclick=()=>swapModal(()=>openAnimalForm());$('#quickNfc').onclick=()=>swapModal(openNfc);$('#quickWater').onclick=()=>swapModal(openWaterForm);}

async function imageData(file){
  if(!file)return null;if(!file.type.startsWith('image/'))throw new Error('Selecione uma imagem válida.');if(file.size>12_000_000)throw new Error('A foto original deve ter no máximo 12 MB.');
  const source=URL.createObjectURL(file);try{const img=new Image();img.src=source;await img.decode();const max=1400,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.84);}finally{URL.revokeObjectURL(source);}
}
function openPostForm(post=null,openCamera=false){
  openModal(post?'EDITAR PUBLICAÇÃO':'NOVA PUBLICAÇÃO',post?'Atualize seu conteúdo':'Compartilhar atualização',`<form id="postForm" class="modal-form"><label class="full">Categoria<select name="category"><option ${post?.category==='Economia de água'?'selected':''}>Economia de água</option><option ${post?.category==='Rebanho'?'selected':''}>Rebanho</option><option ${post?.category==='Tecnologia'?'selected':''}>Tecnologia</option><option ${post?.category==='Conquista'?'selected':''}>Conquista</option></select></label><label class="full">O que aconteceu?<textarea name="content" maxlength="500" placeholder="Conte uma novidade da fazenda..." required>${esc(post?.content||'')}</textarea></label><div class="full media-picker"><label for="galleryInput">${icon('camera')} Galeria</label><label for="cameraInput">${icon('camera')} Câmera</label><input id="galleryInput" type="file" accept="image/*"><input id="cameraInput" type="file" accept="image/*" capture="environment"></div><div id="imagePreview" class="full image-preview ${post?.image_url?'has-image':''}">${post?.image_url?`<img src="${esc(post.image_url)}" alt="Prévia"><button type="button" id="removeImage">Remover imagem</button>`:'<small>A imagem é opcional e será enviada pelo usuário.</small>'}</div><div class="form-error full"></div><button class="main-button orange-button full" type="submit">${post?'Salvar alterações':'Publicar'}</button></form>`);
  let selectedImage=null,removeImage=false;const preview=$('#imagePreview');const choose=async e=>{const file=e.target.files[0];if(!file)return;try{selectedImage=await imageData(file);removeImage=false;preview.classList.add('has-image');preview.innerHTML=`<img src="${selectedImage}" alt="Prévia"><button type="button" id="removeImage">Remover imagem</button>`;bindRemove();}catch(error){$('.form-error',$('#postForm')).textContent=error.message;}};const bindRemove=()=>{$('#removeImage')?.addEventListener('click',()=>{selectedImage=null;removeImage=true;preview.classList.remove('has-image');preview.innerHTML='<small>Imagem removida. Você pode escolher outra.</small>';});};$('#galleryInput').onchange=choose;$('#cameraInput').onchange=choose;bindRemove();if(openCamera)setTimeout(()=>$('#cameraInput').click(),120);
  $('#postForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=$('button[type=submit]',form),body={category:form.category.value,content:form.content.value,image:selectedImage,removeImage};loading(button,true,post?'Salvando...':'Publicando...');try{await request(post?`/api/posts/${post.id}`:'/api/posts',{method:post?'PATCH':'POST',body});state.social=await request('/api/social');closeModal();if(state.route==='community')renderCommunity();if(state.route==='farmFeed')renderFarmFeed();toast(post?'Publicação atualizada.':'Publicado na comunidade.');}catch(err){$('.form-error',form).textContent=err.message;}finally{loading(button,false);}};
}
async function openComments(postId){
  const post=state.social.posts.find(p=>p.id===postId);openModal('COMENTÁRIOS',post?post.farm_name:'Publicação',`<div class="comment-skeleton"><i></i><i></i><i></i></div>`);try{const comments=await request(`/api/posts/${postId}/comments`);renderCommentsBody(postId,comments);}catch(e){$('#modalBody').innerHTML=`<div class="empty">${esc(e.message)}</div>`;}
}
function renderCommentsBody(postId,comments){
  $('#modalBody').innerHTML=`<div class="comment-list">${comments.map(comment=>`<article class="comment-row"><span>${esc(initials(comment.author_name))}</span><div><strong>${esc(comment.author_name)}</strong><p>${esc(comment.content)}</p><small>${ago(comment.created_at)}</small>${comment.mine?`<footer><button data-edit-comment="${comment.id}">Editar</button><button data-delete-comment="${comment.id}">Excluir</button></footer>`:''}</div></article>`).join('')||'<div class="empty small-empty">Seja o primeiro a comentar.</div>'}</div><form id="commentForm" class="comment-form"><input name="content" maxlength="300" placeholder="Escreva um comentário..." required><button type="submit">${icon('arrow')}</button></form>`;
  $('#commentForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=$('button',form);loading(button,true,'...');try{await request(`/api/posts/${postId}/comments`,{method:'POST',body:{content:form.content.value}});const comments=await request(`/api/posts/${postId}/comments`);const post=state.social.posts.find(p=>p.id===postId);if(post)post.comments=comments.length;renderCommentsBody(postId,comments);toast('Comentário publicado.');}catch(error){toast(error.message,true);}finally{loading(button,false);}};
  $$('[data-edit-comment]').forEach(button=>button.onclick=()=>openEditComment(postId,comments.find(c=>c.id===Number(button.dataset.editComment))));$$('[data-delete-comment]').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir este comentário?'))return;try{await request(`/api/comments/${button.dataset.deleteComment}`,{method:'DELETE'});const fresh=await request(`/api/posts/${postId}/comments`);const post=state.social.posts.find(p=>p.id===postId);if(post)post.comments=fresh.length;renderCommentsBody(postId,fresh);toast('Comentário excluído.');}catch(e){toast(e.message,true);}});
}
function openEditComment(postId,comment){swapModal(()=>{openModal('EDITAR COMENTÁRIO','Alterar texto',`<form id="editCommentForm" class="modal-form"><label class="full">Comentário<textarea name="content" maxlength="300" required>${esc(comment.content)}</textarea></label><div class="form-error full"></div><button class="main-button orange-button full">Salvar comentário</button></form>`);$('#editCommentForm').onsubmit=async e=>{e.preventDefault();try{await request(`/api/comments/${comment.id}`,{method:'PATCH',body:{content:e.currentTarget.content.value}});closeModal();await openComments(postId);toast('Comentário atualizado.');}catch(error){$('.form-error',e.currentTarget).textContent=error.message;}};});}
function openPostMenu(postId){
  const post=state.social.posts.find(p=>p.id===postId);if(!post)return;const body=post.mine?`<div class="quick-menu"><button id="editPost">${icon('edit')}<div><strong>Editar publicação</strong><small>Alterar texto, categoria ou imagem</small></div>${icon('chevron')}</button><button id="deletePost" class="danger-action">${icon('trash')}<div><strong>Excluir publicação</strong><small>Remover definitivamente do feed</small></div>${icon('chevron')}</button></div>`:`<div class="quick-menu"><button id="menuFollow">${icon('users')}<div><strong>${post.followed?'Deixar de seguir':'Seguir propriedade'}</strong><small>${esc(post.farm_name)}</small></div>${icon('chevron')}</button><button id="reportPost" class="danger-action">${icon('info')}<div><strong>Denunciar publicação</strong><small>Enviar para análise</small></div>${icon('chevron')}</button></div>`;openModal('PUBLICAÇÃO','Opções',body);
  if(post.mine){$('#editPost').onclick=()=>swapModal(()=>openPostForm(post));$('#deletePost').onclick=async()=>{if(!confirm('Excluir esta publicação? Esta ação não pode ser desfeita.'))return;try{await request(`/api/posts/${postId}`,{method:'DELETE'});state.social=await request('/api/social');closeModal();if(state.route==='farmFeed')renderFarmFeed();else renderCommunity();toast('Publicação excluída.');}catch(e){toast(e.message,true);}};}else{$('#menuFollow').onclick=async()=>{closeModal();await toggleFollow(post.farm_id);};$('#reportPost').onclick=()=>swapModal(()=>openReport(post));}
}
function openReport(post){openModal('DENÚNCIA','Por que deseja denunciar?',`<form id="reportForm" class="modal-form"><label class="full">Motivo<select name="reason"><option>Spam ou propaganda</option><option>Informação falsa</option><option>Conteúdo ofensivo</option><option>Outro motivo</option></select></label><div class="form-error full"></div><button class="main-button orange-button full">Enviar denúncia</button></form>`);$('#reportForm').onsubmit=async e=>{e.preventDefault();try{await request(`/api/posts/${post.id}/report`,{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});closeModal();toast('Denúncia enviada para análise.');}catch(error){$('.form-error',e.currentTarget).textContent=error.message;}};}

function openAnimalForm(tag=''){openModal('NOVO CADASTRO','Adicionar animal',`<form id="animalForm" class="modal-form"><label>Etiqueta NFC<input name="tag" value="${esc(tag)}" placeholder="AG-0001" required></label><label>Nome<input name="name" placeholder="Nome do animal" required></label><label>Espécie<select name="species"><option>Bovino</option><option>Equino</option><option>Ovino</option><option>Caprino</option></select></label><label>Raça<input name="breed" placeholder="Raça"></label><label>Setor<input name="sector" placeholder="Setor ou pasto" required></label><label>Peso (kg)<input name="weight" type="number" min="0"></label><label class="full">Situação<select name="status"><option>Saudável</option><option>Observação</option><option>Tratamento</option></select></label><div class="form-error full"></div><button class="main-button orange-button full" type="submit">Salvar animal</button></form>`);$('#animalForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{await request('/api/animals',{method:'POST',body:Object.fromEntries(new FormData(form))});state.animals=await request('/api/animals');state.nfc=await request('/api/nfc');state.dashboard=await request('/api/dashboard');closeModal();route('animals',true);toast('Animal cadastrado.');}catch(err){$('.form-error',form).textContent=err.message;}};}
function openWaterForm(){openModal('NOVA LEITURA','Registrar consumo',`<form id="waterForm" class="modal-form"><label class="full">Setor<input name="sector" placeholder="Ex.: Irrigação do cacau" required></label><label class="full">Litros utilizados<input name="liters" type="number" min="1" placeholder="Ex.: 680" required></label><div class="form-error full"></div><button class="main-button orange-button full" type="submit">Salvar leitura</button></form>`);$('#waterForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{await request('/api/water',{method:'POST',body:Object.fromEntries(new FormData(form))});[state.water,state.dashboard,state.social]=await Promise.all([request('/api/water'),request('/api/dashboard'),request('/api/social')]);closeModal();route('water',true);toast('Leitura de água salva.');}catch(err){$('.form-error',form).textContent=err.message;}};}
function openReservoirCreate(){openModal('NOVO RESERVATÓRIO','Cadastrar armazenamento',`<form id="newReservoirForm" class="modal-form"><label>Nome<input name="name" placeholder="Reservatório central" required></label><label>Setor<input name="sector" placeholder="Sede" required></label><label>Capacidade (L)<input name="capacity" type="number" min="1" placeholder="20000" required></label><label>Nível inicial (%)<input name="level" type="number" min="0" max="100" value="0" required></label><div class="form-error full"></div><button class="main-button orange-button full">Cadastrar reservatório</button></form>`);$('#newReservoirForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{await request('/api/reservoirs',{method:'POST',body:Object.fromEntries(new FormData(form))});state.water=await request('/api/water');state.dashboard=await request('/api/dashboard');closeModal();renderWater();toast('Reservatório cadastrado.');}catch(error){$('.form-error',form).textContent=error.message;}};}
function openReservoirForm(id,level){openModal('RESERVATÓRIO','Atualizar nível',`<form id="reservoirForm" class="modal-form"><label class="full">Nível: <b id="rangeValue">${level}%</b><input name="level" type="range" min="0" max="100" value="${level}"></label><button class="main-button orange-button full" type="submit">Atualizar</button></form>`);$('[name=level]').oninput=e=>$('#rangeValue').textContent=e.target.value+'%';$('#reservoirForm').onsubmit=async e=>{e.preventDefault();await request(`/api/reservoirs/${id}`,{method:'PATCH',body:Object.fromEntries(new FormData(e.currentTarget))});state.water=await request('/api/water');state.dashboard=await request('/api/dashboard');closeModal();renderWater();toast('Nível atualizado.');};}
function openDroneForm(drone=null){openModal(drone?'MISSÃO DO DRONE':'NOVO DRONE',drone?'Gerenciar dispositivo':'Cadastrar dispositivo',`<form id="droneForm" class="modal-form">${drone?'':`<label>Nome<input name="name" placeholder="Ex.: Drone 01" required></label><label>Modelo<input name="model" placeholder="Modelo do drone" required></label>`}<label class="full">Missão<input name="mission" value="${esc(drone?.mission||'Disponível')}" required></label><label>Status<select name="status"><option ${drone?.status==='Na base'?'selected':''}>Na base</option><option ${drone?.status==='Em voo'?'selected':''}>Em voo</option><option ${drone?.status==='Carregando'?'selected':''}>Carregando</option><option ${drone?.status==='Manutenção'?'selected':''}>Manutenção</option></select></label><label>Bateria (%)<input name="battery" type="number" min="0" max="100" value="${drone?.battery??100}" required></label><div class="form-error full"></div><button class="main-button orange-button full">Salvar</button></form>`);$('#droneForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{const result=await request(drone?`/api/drones/${drone.id}`:'/api/drones',{method:drone?'PATCH':'POST',body:Object.fromEntries(new FormData(form))});[state.drones,state.dashboard,state.social]=await Promise.all([request('/api/drones'),request('/api/dashboard'),request('/api/social')]);closeModal();renderDrones();toast(result.missionCompleted?'Missão concluída e registrada.':drone?'Drone atualizado.':'Drone cadastrado.');}catch(error){$('.form-error',form).textContent=error.message;}};}
async function cleanupNativeNfc(){const plugin=window.Capacitor?.Plugins?.CapacitorNfc;try{await plugin?.stopScanning?.();}catch{}try{await state.nfcNativeListener?.remove?.();}catch{}state.nfcNativeListener=null;}
function nativeNfcCode(event){const record=event?.tag?.ndefMessage?.find(item=>Array.isArray(item.payload)&&item.payload.length);if(record){try{const payload=Uint8Array.from(record.payload),languageLength=payload[0]&63,text=new TextDecoder().decode(payload.slice(1+languageLength)).trim();if(text)return text;}catch{}}const id=event?.tag?.id;if(Array.isArray(id)&&id.length)return`NFC-${id.map(byte=>Number(byte).toString(16).padStart(2,'0')).join('').toUpperCase()}`;return'';}
async function openNfc(){await cleanupNativeNfc();openModal('IDENTIFICAÇÃO NFC','Aproxime a etiqueta',`<div class="nfc-panel"><div class="nfc-rings"><i></i><i></i>${icon('nfc')}</div><p id="nfcStatus">Encoste o celular no brinco NFC do animal.</p><button class="nfc-settings-button hidden" id="openNfcSettings">Ativar NFC nas configurações</button><form id="modalNfcForm" class="comment-form"><input name="tag" placeholder="Ou digite AG-0001" required><button>${icon('arrow')}</button></form></div>`);$('#modalNfcForm').onsubmit=e=>{e.preventDefault();processNfcScan(e.currentTarget.tag.value);};const nativeNfc=window.Capacitor?.Plugins?.CapacitorNfc;if(nativeNfc)try{const support=await nativeNfc.isSupported();if(!support.supported)throw new Error('Este aparelho não possui NFC. Digite o código abaixo.');const adapter=await nativeNfc.getStatus();if(adapter.status==='NFC_DISABLED'){$('#nfcStatus').textContent='O NFC está desligado. Ative-o ou digite o código.';$('#openNfcSettings').classList.remove('hidden');$('#openNfcSettings').onclick=()=>nativeNfc.showSettings();return;}state.nfcNativeListener=await nativeNfc.addListener('nfcEvent',event=>{const code=nativeNfcCode(event);if(code)processNfcScan(code);else toast('A etiqueta não forneceu um código legível.',true);});await nativeNfc.startScanning({invalidateAfterFirstRead:true,alertMessage:'Aproxime a etiqueta NFC do animal.'});$('#nfcStatus').textContent='Leitor NFC nativo ativo. Aproxime a etiqueta.';return;}catch(error){$('#nfcStatus').textContent=error.message||'NFC nativo indisponível. Digite o código abaixo.';}if('NDEFReader'in window)try{const reader=new NDEFReader();await reader.scan();$('#nfcStatus').textContent='Leitor Web NFC ativo. Aproxime a etiqueta.';reader.onreading=event=>processNfcScan(event.serialNumber||[...event.message.records].map(record=>new TextDecoder(record.encoding||'utf-8').decode(record.data)).find(Boolean)||'NFC-LIDO');}catch{$('#nfcStatus').textContent='NFC indisponível ou sem permissão. Digite o código abaixo.';}else $('#nfcStatus').textContent='Use a leitura manual neste navegador.';}
async function processNfcScan(tag){const cleanTag=String(tag||'').trim().toUpperCase();if(!cleanTag)return toast('Informe uma etiqueta NFC.',true);await cleanupNativeNfc();const status=$('#nfcStatus');if(status)status.textContent='Consultando etiqueta...';try{const result=await request('/api/nfc/scan',{method:'POST',body:{tag:cleanTag}});state.nfc=await request('/api/nfc');state.social=await request('/api/social');if(result.animal){openModal('NFC IDENTIFICADO',result.animal.name,`<div class="nfc-result success">${icon('check')}<p><strong>${esc(result.animal.tag)}</strong><span>${esc(result.animal.species)} · ${esc(result.animal.breed)} · ${esc(result.animal.sector)}</span><small>Status: ${esc(result.animal.status)}</small></p><button class="main-button green-button" data-route="animals">Abrir rebanho</button><button class="main-button outline-button" id="scanAgain">Ler outra etiqueta</button></div>`);$('#scanAgain').onclick=openNfc;toast('Animal identificado.');}else{openModal('ETIQUETA NÃO CADASTRADA',cleanTag,`<div class="nfc-result unknown">${icon('nfc')}<p>Esta etiqueta ainda não pertence a um animal da sua fazenda.</p><button class="main-button orange-button" id="registerScannedTag">Cadastrar animal com esta etiqueta</button><button class="main-button outline-button" id="scanAgain">Ler outra etiqueta</button></div>`);$('#registerScannedTag').onclick=()=>swapModal(()=>openAnimalForm(cleanTag));$('#scanAgain').onclick=openNfc;}if(state.route==='nfc')renderNfc();}catch(error){toast(error.message,true);if(status)status.textContent=error.message;}}
async function logout(){try{await request('/api/auth/logout',{method:'POST'});}finally{resetAccountState();document.body.classList.remove('dark-mode','compact-mode','animations-off');showOnly('authView');toast('Sessão encerrada.');}}

function openModal(label,title,body){$('#modalLabel').textContent=label;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;const modal=$('#appModal');if(!modal.open)modal.showModal();$$('[data-close]',modal).forEach(button=>button.onclick=closeModal);}
function closeModal(){cleanupNativeNfc();if($('#appModal').open)$('#appModal').close();}
function swapModal(callback){closeModal();setTimeout(callback,140);}
$$('[data-close]').forEach(button=>button.onclick=closeModal);$('#appModal').onclick=e=>{if(e.target===$('#appModal'))closeModal();};
function ago(value){const date=new Date(String(value).includes('T')?value:String(value).replace(' ','T')+'Z'),seconds=Math.max(0,Math.floor((Date.now()-date.getTime())/1000));if(seconds<45)return'agora';const minutes=Math.floor(seconds/60);if(minutes<60)return`${minutes} min`;const hours=Math.floor(minutes/60);if(hours<24)return`${hours} h`;const days=Math.floor(hours/24);if(days<30)return`${days} d`;return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(date);}
function weekday(value){return new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(new Date(value+'T12:00:00')).replace('.','');}

document.addEventListener('pointerdown',event=>{const button=event.target.closest('button');if(!button||button.disabled||!Number(state.settings.animations)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;button.classList.remove('tap-motion');void button.offsetWidth;button.classList.add('tap-motion');setTimeout(()=>button.classList.remove('tap-motion'),360);});

boot();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
